 r['gain_vs_ots']=r.total_shot_impact-r.normal_ots
 for target in ['sq','make','ft']:
  r['gain_'+target+'_vs_ots']=r['own_'+target]+r['teammate_'+target]-r['normal_ots_'+target]
 if ((r[['gain_sq_vs_ots','gain_make_vs_ots','gain_ft_vs_ots']].sum(axis=1)-r.gain_vs_ots).abs()>1e-9).any():raise ValueError('Gain bridge does not close')
 # Observed passing rate; keep separate from fitted impact and conditional toggle.
 passing=pd.read_csv('/Users/russ/Documents/Codex/basketball/data/csvs/player_stats_export.csv',usecols=['year','nba_id','PASSING_AtRimAssists/100']).rename(columns={'year':'season','nba_id':'player_id','PASSING_AtRimAssists/100':'rim_assists_per100'})
 exposure=pd.read_parquet(ROOT/'cache/five_man_fit/player_role_features_2014_2026.parquet',columns=['year','nba_id','OffPoss']).rename(columns={'year':'season','nba_id':'player_id','OffPoss':'rim_assist_source_possessions'})
 annual=r[r.window.ne('2022-2026')][['player_id','window']].copy();annual['season']=annual.window.astype(int)
