 t=t.replace('<h1>Own shots & teammate shots</h1>','<h1>Five years. Six shooting contributions.</h1>')
 start=t.index('<p>Separating expected scoring value');end=t.index('<div class="controls">',start)
 cards=''.join(f'<div class="card"><b>{name}</b><p>{desc}</p></div>' for name,desc in [('Own SQ / rim','Russell v2 expected midrange/three scoring plus actual rim scoring on the player’s own chances, plus FT replacement value.'),('Teammate SQ / rim','The corresponding scoring baseline on teammates’ chances, including FT replacement value.'),('Own shotmaking','Own midrange/three conversion above or below Russell v2 expectation.'),('Teammate shotmaking','Teammate midrange/three conversion above or below expectation.'),('Own FT','Expected own FT premium above the replacement-shot baseline, including trip frequency.'),('Teammate FT','Expected FT premium on teammates’ chances, including trip frequency.')])
 intro='<p><b>2021–22 through 2025–26.</b> Lineup-adjusted own and teammate shooting impact, now including free throws. SQ retains shooter talent. The standard frozen v2 treatment keeps rim scoring actual; only midrange and threes split into expected value and residual.</p><div class="cards">'+cards+'</div>'
