 t=t.replace('<label>SQ version<select id="source"><option value="improved_hybrid">Improved where available</option><option value="provider">Consistent provider SQ</option></select></label>','<input type="hidden" id="source" value="russell_v2">')
 t=t.replace('<option value="2024-2026">Three-year pooled</option>','<option value="2022-2026">Five-year pooled</option><option value="2022">2021–22</option><option value="2023">2022–23</option>')
