 t=t.replace('<p id="note"></p>','''<div class="downloads"><button id="download-selected">Download this view · CSV</button><a href="downloads/v2_v2_six_2022-2026_results.csv" download>Full five-year CSV</a><a href="downloads/v2_all_results.csv" download>All six windows · CSV</a><a href="downloads/v2_alpha_candidates.csv" download>Alpha search · CSV</a></div><p class="download-note">All result downloads include the research role/talent baseline and teammate surplus, normal oTS, the six conditional rates, six additive contributions, shot share, and opportunity counts. The current-view download follows your filters.</p><p id="note"></p>''')
